{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
d = df.dropna(subset=['tensile_mpa']).copy()
for c in ['carbon_pct','porosity']:
    print(c)
    for l in sorted(d.lab.unique()):
        dd = d[d.lab==l]
        m = smf.ols(f'tensile_mpa ~ {c}', data=dd).fit()
        print(f"   {l}: coef={m.params[c]: .3f} p={m.pvalues[c]:.3f} n={len(dd)}")
"}
